  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrinos as a new means of observing the universe, a major opening of the multi-messenger era.",
        "attribution": "Halzen was central to conceiving and building IceCube and to the program that produced the discovery; the result depended on a large collaboration.",
        "maturity": "The diffuse astrophysical neutrino signal is established by sustained data and analysis, though its individual sources remain uncertain.",
        "uncertainties": [
          "The Nobel-scale contribution of a single leader must be weighed against the essential work of the full IceCube collaboration."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision mapping of the cosmic microwave background made cosmological parameters substantially more secure and helped establish the standard cosmological model.",
        "attribution": "Bennett and Page led key experimental and instrument work, while Spergel contributed centrally to the cosmological interpretation; the mission was a broad team effort.",
        "maturity": "The measurements and their cosmological implications have been extensively tested and refined by later observations.",
        "uncertainties": [
          "WMAP followed COBE's landmark discovery and was later surpassed in precision by Planck, complicating the case for singling out this mission."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The ATLAS and CMS detectors enabled the Higgs boson discovery and a decisive test of the Standard Model's mechanism for particle masses.",
        "attribution": "These leaders made major contributions to the experiments and their construction; the achievement belongs to exceptionally large international collaborations.",
        "maturity": "The Higgs discovery is secure, and subsequent measurements have established its properties with growing precision.",
        "uncertainties": [
          "Credit for detector leadership and the discovery must be distinguished from the indispensable contributions of thousands of collaborators."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Nial R. Tanvir"
      ],
      "assessment": {
        "nobel_worthiness": "The kilonova interpretation connected neutron-star mergers with the creation of heavy elements and gave gravitational-wave events a powerful electromagnetic counterpart.",
        "attribution": "Metzger and Kasen helped develop the theoretical account, while Tanvir was among the leaders of the pivotal observational work; prediction and observation are distinct contributions.",
        "maturity": "The 2017 event firmly established a kilonova associated with a neutron-star merger, though the detailed element yields and merger contributions remain under study.",
        "uncertainties": [
          "The precise division of credit across theoretical work and the many teams that observed GW170817 is difficult to compress into three laureates."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and provide exceptionally sensitive tools for testing fundamental physics and measuring gravitational potential.",
        "attribution": "Katori introduced the optical lattice clock concept, and Ye made major contributions to realizing and advancing high-performance systems.",
        "maturity": "The technique is mature, with independent implementations and rapidly improving clock performance.",
        "uncertainties": [
          "The field has advanced through broad international work, so the boundary between the foundational invention and later realization deserves careful review."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault-tolerant computation showed how quantum information can be protected despite noise, a foundational advance now central to quantum technology.",
        "attribution": "Shor and Steane developed influential early codes, while Kitaev established key theoretical frameworks for fault tolerance and topological protection.",
        "maturity": "The theory is well established and experimental demonstrations are advancing, although large-scale fault-tolerant computation remains unrealized.",
        "uncertainties": [
          "The eventual scope and practical reach of fault-tolerant quantum computing are not yet known."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser introduced a distinct laser principle based on semiconductor band engineering and became a useful source across important infrared applications.",
        "attribution": "Capasso and Faist were central to the invention and first realization; Cho's semiconductor expertise and leadership were important to the enabling work.",
        "maturity": "The device has been demonstrated, developed over decades, and adopted in practical technologies.",
        "uncertainties": [
          "The relative credit for the conceptual invention, semiconductor structure, and first working device should be examined closely."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Christopher Thompson",
        "Chryssa Kouveliotou",
        "Robert C. Duncan"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetars revealed an extreme neutron-star population powered by magnetic energy and materially changed understanding of high-energy stellar phenomena.",
        "attribution": "Duncan and Thompson developed the influential magnetar model, while Kouveliotou led observations that identified and characterized magnetars.",
        "maturity": "Multiple sources and observational signatures support the class, and its basic physical picture has endured.",
        "uncertainties": [
          "The mechanisms behind particular bursts and the full range of magnetar behavior remain active research questions."
        ]
      }
    }
  ]
}
